window.VO = [{"id":"o01","text":"You are under digital arrest.","at":0.24,"t0":0.12,"t1":1.938},{"id":"o02","text":"Do not hang up.","at":4.276,"t0":2.138,"t1":3.593},{"id":"n01","text":"Would you fall for this?","at":7.786,"t0":3.893,"t1":5.711},{"id":"n02","text":"Then find the three mistakes on this call.","at":13.822,"t0":6.911,"t1":9.82},{"id":"o03","text":"A parcel in your name.","at":20.14,"t0":10.07,"t1":11.888},{"id":"o04","text":"Five fake passports.","at":24.176,"t0":12.088,"t1":13.179},{"id":"o05","text":"Your pension account is frozen.","at":28.758,"t0":14.379,"t1":16.197},{"id":"o06","text":"Photograph your gold.","at":32.834,"t0":16.417,"t1":17.508},{"id":"o07","text":"Stay in your room, madam.","at":35.516,"t0":17.758,"t1":19.576},{"id":"o08","text":"Tell no one.","at":39.552,"t0":19.776,"t1":20.867},{"id":"o09","text":"That is my team.","at":45.834,"t0":22.917,"t1":24.372},{"id":"n03","text":"You just looked at your door, didn't you?","at":49.544,"t0":24.772,"t1":27.681},{"id":"n04","text":"Even though his badge can't spell police.","at":55.662,"t0":27.831,"t1":30.376},{"id":"n05","text":"And even if it could, there's no such thing as a digital arrest.","at":61.252,"t0":30.626,"t1":35.353},{"id":"n06","text":"You only know that because somebody told you.","at":71.508,"t0":35.754,"t1":38.663},{"id":"n07","text":"Nobody told her.","at":78.026,"t0":39.013,"t1":40.104},{"id":"n08","text":"This was never your call.","at":81.908,"t0":40.954,"t1":42.772},{"id":"n09","text":"While you hunted for mistakes, she took off her bangles.","at":87.144,"t0":43.572,"t1":47.208},{"id":"n10","text":"She corrected exam papers for thirty years, and she never saw that badge, because she wasn't looking for his mistakes.","at":95.416,"t0":47.708,"t1":54.981},{"id":"n11","text":"She was trying to prove she hadn't made one.","at":110.662,"t0":55.331,"t1":58.604},{"id":"n12","text":"That was never his team, and that was never his cooker.","at":123.008,"t0":61.504,"t1":65.504},{"id":"n13","text":"It was you.","at":131.608,"t0":65.804,"t1":66.895},{"id":"o10","text":"Tell them nothing, or they are arrested too.","at":134.69,"t0":67.345,"t1":70.254},{"id":"m01","text":"I'm fine, beta.","at":142.208,"t0":71.104,"t1":72.195},{"id":"m02","text":"You eat.","at":145.09,"t0":72.545,"t1":73.272},{"id":"n14","text":"So you did.","at":150.844,"t0":75.422,"t1":76.513},{"id":"n15","text":"That's three.","at":154.926,"t0":77.463,"t1":78.19},{"id":"n16","text":"You think you'd never fall for this.","at":158.28,"t0":79.14,"t1":81.685},{"id":"n17","text":"You'd just believe her.","at":163.87,"t0":81.935,"t1":83.39},{"id":"n18","text":"Have you told your mother?","at":169.78,"t0":84.89,"t1":86.708},{"id":"n19","text":"Would she tell you?","at":174.616,"t0":87.308,"t1":88.763}];
